    AssociateVPCWithHostedZoneRequest.add_member(:hosted_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceId, location_name: 'HostedZoneId', traits: {"smithy.api#documentation" => "<p>The ID of the private hosted zone that you want to associate an Amazon VPC\n\t\t\twith.</p>\n         <p>Note that you can't associate a VPC with a hosted zone that doesn't have an existing\n\t\t\tVPC association.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
