    ChangeInfo.add_member(:submitted_at, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeStamp, location_name: 'SubmittedAt', traits: {"smithy.api#documentation" => "<p>The date and time that the change request was submitted in <a href=\"https://en.wikipedia.org/wiki/ISO_8601\">ISO 8601 format</a> and Coordinated\n\t\t\tUniversal Time (UTC). For example, the value <code>2017-03-27T17:48:16.751Z</code>\n\t\t\trepresents March 27, 2017 at 17:48:16.751 UTC.</p>", "smithy.api#required" => {}}))
