    ChangeTagsForResourceRequest.add_member(:add_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'AddTags', traits: {"smithy.api#documentation" => "<p>A complex type that contains a list of the tags that you want to add to the specified\n\t\t\thealth check or hosted zone and/or the tags that you want to edit <code>Value</code>\n\t\t\tfor.</p>\n         <p>You can add a maximum of 10 tags to a health check or a hosted zone.</p>"}))
