    GeoLocation.add_member(:continent_code, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationContinentCode, location_name: 'ContinentCode', traits: {"smithy.api#documentation" => "<p>The two-letter code for the continent.</p>\n         <p>Amazon Route 53 supports the following continent codes:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>AF</b>: Africa</p>\n            </li>\n            <li>\n               <p>\n                  <b>AN</b>: Antarctica</p>\n            </li>\n            <li>\n               <p>\n                  <b>AS</b>: Asia</p>\n            </li>\n            <li>\n               <p>\n                  <b>EU</b>: Europe</p>\n            </li>\n            <li>\n               <p>\n                  <b>OC</b>: Oceania</p>\n            </li>\n            <li>\n               <p>\n                  <b>NA</b>: North America</p>\n            </li>\n            <li>\n               <p>\n                  <b>SA</b>: South America</p>\n            </li>\n         </ul>\n         <p>Constraint: Specifying <code>ContinentCode</code> with either <code>CountryCode</code>\n\t\t\tor <code>SubdivisionCode</code> returns an <code>InvalidInput</code> error.</p>"}))
    GeoLocation.add_member(:country_code, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationCountryCode, location_name: 'CountryCode', traits: {"smithy.api#documentation" => "<p>For geolocation resource record sets, the two-letter code for a country.</p>\n         <p>Amazon Route 53 uses the two-letter country codes that are specified in <a href=\"https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2\">ISO standard 3166-1\n\t\t\t\talpha-2</a>.</p>\n         <p>Route 53 also supports the country code <b>UA</b> for\n\t\t\tUkraine.</p>"}))
    GeoLocation.add_member(:subdivision_code, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationSubdivisionCode, location_name: 'SubdivisionCode', traits: {"smithy.api#documentation" => "<p>For geolocation resource record sets, the two-letter code for a state of the United\n\t\t\tStates. Route 53 doesn't support any other values for <code>SubdivisionCode</code>. For\n\t\t\ta list of state abbreviations, see <a href=\"https://pe.usps.com/text/pub28/28apb.htm\">Appendix B: Two–Letter State and Possession Abbreviations</a> on the United\n\t\t\tStates Postal Service website. </p>\n         <p>If you specify <code>subdivisioncode</code>, you must also specify <code>US</code> for\n\t\t\t\t<code>CountryCode</code>. </p>"}))
    GeoLocation.type = Types::GeoLocation
