    GeoLocationDetails.add_member(:continent_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationContinentName, location_name: 'ContinentName', traits: {"smithy.api#documentation" => "<p>The full name of the continent.</p>"}))
