    GeoLocationDetails.add_member(:country_name, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationCountryName, location_name: 'CountryName', traits: {"smithy.api#documentation" => "<p>The name of the country.</p>"}))
    GeoLocationDetails.add_member(:subdivision_code, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoLocationSubdivisionCode, location_name: 'SubdivisionCode', traits: {"smithy.api#documentation" => "<p>The code for the subdivision, such as a particular state within the United States. For\n\t\t\ta list of US state abbreviations, see <a href=\"https://pe.usps.com/text/pub28/28apb.htm\">Appendix B: Two–Letter State and\n\t\t\t\tPossession Abbreviations</a> on the United States Postal Service website. For a\n\t\t\tlist of all supported subdivision codes, use the <a href=\"https://docs.aws.amazon.com/Route53/latest/APIReference/API_ListGeoLocations.html\">ListGeoLocations</a>\n\t\t\tAPI.</p>"}))
