    GetHostedZoneLimitResponse.add_member(:count, Smithy::Schema::Shapes::ShapeRef.new(shape: UsageCount, location_name: 'Count', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The current number of entities that you have created of the specified type. For\n\t\t\texample, if you specified <code>MAX_RRSETS_BY_ZONE</code> for the value of\n\t\t\t\t<code>Type</code> in the request, the value of <code>Count</code> is the current\n\t\t\tnumber of records that you have created in the specified hosted zone.</p>", "smithy.api#required" => {}}))
