    HostedZone.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: DNSName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the domain. For public hosted zones, this is the name that you have\n\t\t\tregistered with your DNS registrar.</p>\n         <p>For information about how to specify characters other than <code>a-z</code>,\n\t\t\t\t<code>0-9</code>, and <code>-</code> (hyphen) and how to specify internationalized\n\t\t\tdomain names, see <a href=\"https://docs.aws.amazon.com/Route53/latest/APIReference/API_CreateHostedZone.html\">CreateHostedZone</a>.</p>", "smithy.api#required" => {}}))
    HostedZone.add_member(:caller_reference, Smithy::Schema::Shapes::ShapeRef.new(shape: Nonce, location_name: 'CallerReference', traits: {"smithy.api#documentation" => "<p>The value that you specified for <code>CallerReference</code> when you created the\n\t\t\thosted zone.</p>", "smithy.api#required" => {}}))
    HostedZone.add_member(:config, Smithy::Schema::Shapes::ShapeRef.new(shape: HostedZoneConfig, location_name: 'Config', traits: {"smithy.api#documentation" => "<p>A complex type that includes the <code>Comment</code> and <code>PrivateZone</code>\n\t\t\telements. If you omitted the <code>HostedZoneConfig</code> and <code>Comment</code>\n\t\t\telements from the request, the <code>Config</code> and <code>Comment</code> elements\n\t\t\tdon't appear in the response.</p>"}))
