    KeySigningKey.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>A string used to identify a key-signing key (KSK). <code>Name</code> can include\n\t\t\tnumbers, letters, and underscores (_). <code>Name</code> must be unique for each\n\t\t\tkey-signing key in the same hosted zone.</p>"}))
    KeySigningKey.add_member(:kms_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyString, location_name: 'KmsArn', traits: {"smithy.api#documentation" => "<p>The Amazon resource name (ARN) used to identify the customer managed key in Key Management Service (KMS). The <code>KmsArn</code> must be unique for each\n\t\t\tkey-signing key (KSK) in a single hosted zone.</p>\n         <p>You must configure the customer managed key as follows:</p>\n         <dl>\n            <dt>Status</dt>\n            <dd>\n               <p>Enabled</p>\n            </dd>\n            <dt>Key spec</dt>\n            <dd>\n               <p>ECC_NIST_P256</p>\n            </dd>\n            <dt>Key usage</dt>\n            <dd>\n               <p>Sign and verify</p>\n            </dd>\n            <dt>Key policy</dt>\n            <dd>\n               <p>The key policy must give permission for the following actions:</p>\n               <ul>\n                  <li>\n                     <p>DescribeKey</p>\n                  </li>\n                  <li>\n                     <p>GetPublicKey</p>\n                  </li>\n                  <li>\n                     <p>Sign</p>\n                  </li>\n               </ul>\n               <p>The key policy must also include the Amazon Route 53 service in the\n\t\t\t\t\t\tprincipal for your account. Specify the following:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>\"Service\": \"dnssec-route53.amazonaws.com\"</code>\n                     </p>\n                  </li>\n               </ul>\n            </dd>\n         </dl>\n         <p>For more information about working with the customer managed key in KMS, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html\">Key Management Service\n\t\t\t\tconcepts</a>.</p>"}))
    KeySigningKey.add_member(:flag, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyInteger, location_name: 'Flag', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>An integer that specifies how the key is used. For key-signing key (KSK), this value\n\t\t\tis always 257.</p>"}))
    KeySigningKey.add_member(:signing_algorithm_mnemonic, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyString, location_name: 'SigningAlgorithmMnemonic', traits: {"smithy.api#documentation" => "<p>A string used to represent the signing algorithm. This value must follow the\n\t\t\tguidelines provided by <a href=\"https://tools.ietf.org/html/rfc8624#section-3.1\">RFC-8624 Section 3.1</a>. </p>"}))
    KeySigningKey.add_member(:signing_algorithm_type, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyInteger, location_name: 'SigningAlgorithmType', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>An integer used to represent the signing algorithm. This value must follow the\n\t\t\tguidelines provided by <a href=\"https://tools.ietf.org/html/rfc8624#section-3.1\">RFC-8624 Section 3.1</a>. </p>"}))
    KeySigningKey.add_member(:digest_algorithm_mnemonic, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyString, location_name: 'DigestAlgorithmMnemonic', traits: {"smithy.api#documentation" => "<p>A string used to represent the delegation signer digest algorithm. This value must\n\t\t\tfollow the guidelines provided by <a href=\"https://tools.ietf.org/html/rfc8624#section-3.3\">RFC-8624 Section 3.3</a>.\n\t\t</p>"}))
