    KeySigningKey.add_member(:key_tag, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyTag, location_name: 'KeyTag', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>An integer used to identify the DNSSEC record for the domain name. The process used to\n\t\t\tcalculate the value is described in <a href=\"https://tools.ietf.org/rfc/rfc4034.txt\">RFC-4034 Appendix B</a>.</p>"}))
    KeySigningKey.add_member(:digest_value, Smithy::Schema::Shapes::ShapeRef.new(shape: SigningKeyString, location_name: 'DigestValue', traits: {"smithy.api#documentation" => "<p>A cryptographic digest of a DNSKEY resource record (RR). DNSKEY records are used to\n\t\t\tpublish the public key that resolvers can use to verify DNSSEC signatures that are used\n\t\t\tto secure certain kinds of information provided by the DNS system.</p>"}))
